-- Referencia de entidades de etapas 1-3; sin tabla de propuestas ni huella offline.
-- Adopción de una base existente solo tras comparar el esquema en una copia.
create table "${flyway:defaultSchema}".aportes_pareja (fecha date not null, monto numeric(15,2) not null, fecha_creacion timestamp(6), id bigint generated by default as identity, pareja_id bigint not null, usuario_id bigint not null, moneda varchar(10) not null, notas varchar(500), primary key (id));
create table "${flyway:defaultSchema}".asientos_contables (fecha_operacion date not null, tasa_cambio numeric(20,8), fecha_creacion timestamp(6) not null, id bigint generated by default as identity, transaccion_origen_id bigint not null, usuario_id bigint not null, tipo_evento varchar(24) not null, tipo_movimiento varchar(30) check (tipo_movimiento in ('INGRESO','GASTO','TRANSFERENCIA','SALDO_INICIAL')), descripcion varchar(200) not null, primary key (id));
create table "${flyway:defaultSchema}".auditoria_transacciones (fecha_evento timestamp(6) with time zone not null, id bigint generated by default as identity, transaccion_id bigint not null, usuario_id bigint not null, accion varchar(12) not null, antes_json text, despues_json text, primary key (id));
create table "${flyway:defaultSchema}".categorias (activo boolean not null default true not null, color varchar(7), id bigint generated by default as identity, usuario_id bigint, tipo varchar(30) not null check (tipo in ('INGRESO','GASTO','TRANSFERENCIA','SALDO_INICIAL')), icono varchar(50), nombre varchar(80) not null, primary key (id));
create table "${flyway:defaultSchema}".cuentas (activo boolean not null, cashback_limite_mensual numeric(15,2), cashback_porcentaje numeric(5,2), dia_corte integer, dia_pago integer, limite_credito numeric(15,2), limite_retenido numeric(15,2), saldo_actual numeric(15,2) not null, fecha_creacion timestamp(6), id bigint generated by default as identity, usuario_id bigint not null, version BIGINT NOT NULL DEFAULT 0 not null, moneda varchar(10) not null default 'MXN' not null, tipo varchar(30) not null check (tipo in ('EFECTIVO','DEBITO','CREDITO','AHORRO','INVERSION')), institucion_financiera varchar(60), nombre varchar(100) not null, descripcion varchar(255), primary key (id));
create table "${flyway:defaultSchema}".gastos_pareja (fecha date not null, monto numeric(15,2) not null, fecha_creacion timestamp(6), id bigint generated by default as identity, pagado_por_id bigint not null, pareja_id bigint not null, moneda varchar(10) not null, descripcion varchar(200) not null, primary key (id));
create table "${flyway:defaultSchema}".lineas_asiento (moneda varchar(3) not null, monto numeric(15,2) not null, asiento_id bigint not null, categoria_id bigint, cuenta_financiera_id bigint, id bigint generated by default as identity, lado varchar(8) not null check (lado in ('DEBE','HABER')), codigo_cuenta varchar(100) not null, nombre_cuenta varchar(200) not null, primary key (id));
create table "${flyway:defaultSchema}".pagos_pareja (fecha date not null, monto numeric(15,2) not null, beneficiario_id bigint not null, fecha_creacion timestamp(6), id bigint generated by default as identity, pagador_id bigint not null, pareja_id bigint not null, registrado_por_id bigint, moneda varchar(10) not null, notas varchar(500), primary key (id));
create table "${flyway:defaultSchema}".parejas (activa boolean not null, pendiente boolean not null default false not null, fecha_aceptacion timestamp(6), fecha_creacion timestamp(6), id bigint generated by default as identity, propietario_historial_id bigint, usuario_a_id bigint not null, usuario_b_id bigint not null, version bigint not null default 0 not null, moneda varchar(10) not null default 'MXN' not null, nombre_remitente_invitacion varchar(100), correo_destinatario_invitacion varchar(150), correo_remitente_invitacion varchar(150), primary key (id));
create table "${flyway:defaultSchema}".plantillas_recurrentes (activa boolean not null, cuotas_pagadas integer, cuotas_totales integer, fecha_ancla date, monto numeric(15,2) not null, monto_pendiente numeric(15,2), siguiente_fecha date not null, categoria_id bigint, cuenta_id bigint not null, fecha_creacion timestamp(6), id bigint generated by default as identity, usuario_id bigint not null, version bigint not null default 0 not null, compra_msi_id uuid, frecuencia varchar(20) not null check (frecuencia in ('SEMANAL','QUINCENAL','MENSUAL','ANUAL')), tipo varchar(30) not null check (tipo in ('INGRESO','GASTO','TRANSFERENCIA','SALDO_INICIAL')), notas varchar(500), primary key (id));
create table "${flyway:defaultSchema}".presupuestos (anio integer not null, mes integer not null, moneda varchar(3) not null default 'MXN' not null, monto_limite numeric(15,2) not null, categoria_id bigint not null, id bigint generated by default as identity, usuario_id bigint not null, primary key (id), constraint uk_presupuesto_usuario_cat_periodo unique (usuario_id, categoria_id, mes, anio));
create table "${flyway:defaultSchema}".refresh_tokens (revocado boolean not null, token_version integer not null, fecha_creacion timestamp(6) with time zone not null, fecha_expiracion timestamp(6) with time zone not null, fecha_rotacion timestamp(6) with time zone, id bigint generated by default as identity, usuario_id bigint not null, token_hash varchar(64) not null unique, primary key (id));
create table "${flyway:defaultSchema}".repartos_gasto (monto numeric(15,2) not null, porcentaje numeric(5,2), gasto_id bigint not null, id bigint generated by default as identity, usuario_id bigint not null, tipo varchar(30) not null check (tipo in ('IGUAL','PORCENTAJE','EXACTO')), primary key (id), constraint uq_reparto_gasto_usuario unique (gasto_id, usuario_id));
create table "${flyway:defaultSchema}".suscripciones_notificacion_push (creada_en timestamp(6) not null, id bigint generated by default as identity, usuario_id bigint not null, secreto_auth varchar(100) not null, clave_publica varchar(200) not null, endpoint varchar(2048) not null unique, primary key (id));
create table "${flyway:defaultSchema}".tokens_recuperacion_password (usado boolean not null, fecha_creacion timestamp(6) with time zone not null, fecha_expiracion timestamp(6) with time zone not null, id bigint generated by default as identity, usuario_id bigint not null, token_hash varchar(64) not null unique, primary key (id));
create table "${flyway:defaultSchema}".transacciones (fecha date not null, monto numeric(15,2) not null, monto_destino numeric(15,2), tasa_cambio numeric(20,8), cashback_origen_id bigint unique, categoria_id bigint, cuenta_destino_id bigint, cuenta_id bigint, fecha_creacion timestamp(6), id bigint generated by default as identity, usuario_id bigint not null, cuenta_destino_moneda_historica varchar(10), cuenta_moneda_historica varchar(10), client_request_id uuid unique, compra_msi_id uuid, metodo_captura varchar(20) check (metodo_captura in ('TEXTO','VOZ','WHATSAPP')), tipo varchar(30) not null check (tipo in ('INGRESO','GASTO','TRANSFERENCIA','SALDO_INICIAL')), cuenta_destino_nombre_historico varchar(100), cuenta_nombre_historico varchar(100), descripcion varchar(200) not null, notas varchar(500), primary key (id));
create table "${flyway:defaultSchema}".usuarios (activo boolean not null, moneda_preferida varchar(3) not null default 'MXN' not null, notificaciones_whatsapp boolean not null default false not null, ocultar_montos boolean not null default false not null, referencia_historica boolean not null default false not null, token_version integer not null default 0 not null, whatsapp_pin_failed_attempts integer not null default 0 not null, fecha_creacion timestamp(6), id bigint generated by default as identity, whatsapp_pin_expires_at timestamp(6), whatsapp_pin_issued_at timestamp(6), tema_preferido varchar(10) not null default 'CLARO' not null, whatsapp_pin_phone varchar(16) unique, rol varchar(30) not null check (rol in ('ROLE_USER','ROLE_ADMIN')), telefono varchar(30), nombre varchar(100) not null, whatsapp_pin_hash varchar(100), email varchar(150) not null unique, google_subject varchar(255) unique, password_hash varchar(255) not null, primary key (id));
create index idx_aporte_pareja on "${flyway:defaultSchema}".aportes_pareja (pareja_id, fecha);
create index idx_asiento_usuario_fecha on "${flyway:defaultSchema}".asientos_contables (usuario_id, fecha_operacion);
create index idx_auditoria_transaccion_usuario_fecha on "${flyway:defaultSchema}".auditoria_transacciones (usuario_id, fecha_evento);
