create index idx_linea_cuenta_codigo_moneda on "${flyway:defaultSchema}".lineas_asiento (codigo_cuenta, moneda);
create index idx_pago_pareja on "${flyway:defaultSchema}".pagos_pareja (pareja_id, fecha);
create index idx_pareja_usuario_a on "${flyway:defaultSchema}".parejas (usuario_a_id);
create index idx_pareja_usuario_b on "${flyway:defaultSchema}".parejas (usuario_b_id);
create index idx_plantilla_recurrente_usuario_fecha on "${flyway:defaultSchema}".plantillas_recurrentes (usuario_id, siguiente_fecha);
create index idx_refresh_usuario_fecha on "${flyway:defaultSchema}".refresh_tokens (usuario_id, fecha_creacion);
create index idx_reparto_gasto on "${flyway:defaultSchema}".repartos_gasto (gasto_id);
create index idx_push_suscripcion_usuario on "${flyway:defaultSchema}".suscripciones_notificacion_push (usuario_id);
create index idx_reset_usuario_fecha on "${flyway:defaultSchema}".tokens_recuperacion_password (usuario_id, fecha_creacion);
create index idx_transaccion_usuario_fecha on "${flyway:defaultSchema}".transacciones (usuario_id, fecha);
create index idx_transaccion_cuenta on "${flyway:defaultSchema}".transacciones (cuenta_id);
